#!/usr/bin/env bash
# Offline assertions over the artifact-status contract: a completed spec's frontmatter
# status must agree with its row on the sprint board.
# Run with: bash tools/artifact-status-assertions.sh
#
# SCOPE: records. Reads only tracked files under _bmad-output/. Contacts no external
# system, so it can report nothing about the pipeline, DuckDB, or any live data state.
#
# WHY THIS EXISTS. sprint-status.yaml is regenerated by bmad-sprint-planning, while a
# spec's frontmatter `status:` is advanced by bmad-build as it works. Nothing tied the
# two together, so they drift silently: caught 2026-08-20 with Story 1.8, whose spec
# read `status: done` (work committed in 0400f54) while the board still read `review`
# from 2026-08-08. A status view reports the board faithfully and therefore repeats the
# stale value rather than flagging it -- only a cross-artifact check catches this.
#
# Ported from howdoidata/manalink's tools/artifact-status-assertions.sh. That repo's
# sidecar-board handling (sprint-status-r1.yaml et al., for parallel trackers with
# colliding story ids) is deliberately omitted: this repo has exactly one board.
#
# NOT a regression harness, and deliberately not named `.test.sh`. It has no subject
# tool -- there is no `artifact-status` program it exercises. It asserts a contract
# over records. The fixture cases below exist to prove the live check can actually go
# red; a guard nobody has watched fail is not evidence.

set -u -o pipefail

TOOLS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${TOOLS_DIR}/.." && pwd)"
ARTIFACTS_REL="_bmad-output/implementation-artifacts"
TEMP_ROOT="$(mktemp -d "${TMPDIR:-/tmp}/artifact-status-assertions-XXXXXX")" || {
  echo "FATAL: could not create temporary test directory" >&2
  exit 1
}
trap 'rm -rf "$TEMP_ROOT"' EXIT

PASS=0
FAIL=0

pass() { echo "PASS: $1"; PASS=$((PASS + 1)); }
fail() { echo "FAIL: $1" >&2; FAIL=$((FAIL + 1)); }

trim() {
  local value="$1"
  value="${value#"${value%%[![:space:]]*}"}"
  printf '%s' "${value%"${value##*[![:space:]]}"}"
}

# Read a story's status out of the board's `development_status:` block. Matches either
# the bare story id (`1-8`) or the full slugged key (`1-8-advisory-build-validation-logged`),
# since the board uses full slugs while a spec filename yields the numeric id.
board_status() {
  local board="$1" story_id="$2" line key status
  while IFS= read -r line; do
    [[ "$line" =~ ^[^[:space:]] ]] && break
    [[ "$line" =~ ^[[:space:]]{2}([^:]+):[[:space:]]*([a-z-]+)[[:space:]]*$ ]] || continue
    key="$(trim "${BASH_REMATCH[1]}")"
    status="${BASH_REMATCH[2]}"
    [[ "$key" == "$story_id" || "$key" == "$story_id"-* ]] && { printf '%s\n' "$status"; return 0; }
  done < <(sed -n '/^development_status:/,$p' "$board" | sed '1d')
  return 1
}

check_repository() {
  local root="$1" artifacts board
  artifacts="$root/$ARTIFACTS_REL"
  board="$artifacts/sprint-status.yaml"
  local spec base story_id spec_status expected
  local errors=0

  [[ -f "$board" ]] || { echo "missing board: $board" >&2; return 1; }

  shopt -s nullglob
  for spec in "$artifacts"/spec-[0-9]*-[0-9]*-*.md; do
    base="${spec##*/}"
    [[ "$base" =~ ^spec-([0-9]+)-([0-9]+)- ]] || continue
    story_id="${BASH_REMATCH[1]}-${BASH_REMATCH[2]}"
    spec_status="$(sed -n '/^---$/,/^---$/p' "$spec" | sed -nE "s/^status:[[:space:]]*['\"]?([a-z-]+)['\"]?[[:space:]]*$/\1/p" | head -n 1)"
    # Only completed specs are an artifact-status invariant. An active spec uses
    # workflow states (in-progress, awaiting-operator) whose names need not match the
    # board's own vocabulary, and which legitimately lead or lag the board mid-story.
    [[ "$spec_status" == "done" ]] || continue
    expected="$(board_status "$board" "$story_id")" || {
      echo "STATUS CONTRADICTION: story $story_id has completed spec status done but no board entry" >&2
      errors=$((errors + 1)); continue
    }
    if [[ "$expected" != "$spec_status" ]]; then
      echo "STATUS CONTRADICTION: story $story_id expected board status $expected, observed spec status $spec_status" >&2
      errors=$((errors + 1))
    fi
  done
  shopt -u nullglob

  [[ "$errors" -eq 0 ]]
}

# A fixture tree carrying a known-good board plus one completed spec, built from
# scratch rather than copied from the live repo -- the live repo is the subject under
# test, so seeding fixtures from it would make these cases pass or fail with it.
make_fixture() {
  local fixture="$1"
  mkdir -p "$fixture/$ARTIFACTS_REL"
  cat > "$fixture/$ARTIFACTS_REL/sprint-status.yaml" <<'YAML'
development_status:
  epic-1: in-progress
  1-1-a-finished-story: done
  1-2-an-active-story: in-progress
  epic-1-retrospective: optional
YAML
  cat > "$fixture/$ARTIFACTS_REL/spec-1-1-a-finished-story.md" <<'MD'
---
status: 'done'
---
# A finished story
MD
  cat > "$fixture/$ARTIFACTS_REL/spec-1-2-an-active-story.md" <<'MD'
---
status: 'in-progress'
---
# An active story
MD
}

echo "=== Agreeing board and spec ==="
VALID="$TEMP_ROOT/valid"
make_fixture "$VALID"
if check_repository "$VALID"; then
  pass "completed spec matching its board entry passes"
else
  fail "valid fixture reported a contradiction"
fi

echo ""
echo "=== Board lags a completed spec ==="
STALE="$TEMP_ROOT/stale"
make_fixture "$STALE"
STALE_OUTPUT="$TEMP_ROOT/stale-output.txt"
sed 's/^  1-1-a-finished-story: done$/  1-1-a-finished-story: review/' \
  "$STALE/$ARTIFACTS_REL/sprint-status.yaml" > "$STALE/board.tmp" \
  && mv "$STALE/board.tmp" "$STALE/$ARTIFACTS_REL/sprint-status.yaml"
if check_repository "$STALE" >"$STALE_OUTPUT" 2>&1; then
  fail "stale board unexpectedly passed"
else
  grep -q "story 1-1 expected board status review, observed spec status done" "$STALE_OUTPUT" \
    && pass "stale board fails, naming story key, expected, and observed statuses" \
    || fail "stale-board failure did not name the required contradiction"
fi

echo ""
echo "=== Completed spec with no board entry ==="
ORPHAN="$TEMP_ROOT/orphan"
make_fixture "$ORPHAN"
ORPHAN_OUTPUT="$TEMP_ROOT/orphan-output.txt"
grep -v '^  1-1-a-finished-story:' "$ORPHAN/$ARTIFACTS_REL/sprint-status.yaml" > "$ORPHAN/board.tmp" \
  && mv "$ORPHAN/board.tmp" "$ORPHAN/$ARTIFACTS_REL/sprint-status.yaml"
if check_repository "$ORPHAN" >"$ORPHAN_OUTPUT" 2>&1; then
  fail "completed spec with no board entry unexpectedly passed"
else
  grep -q "story 1-1 has completed spec status done but no board entry" "$ORPHAN_OUTPUT" \
    && pass "completed spec with no board entry fails" \
    || fail "orphan failure did not name the required contradiction"
fi

echo ""
echo "=== Active spec is exempt ==="
ACTIVE="$TEMP_ROOT/active"
make_fixture "$ACTIVE"
# The board says done, the spec still says in-progress. Not a contradiction this check
# owns: only a *completed spec* is the invariant, so an in-flight story whose board
# entry moved first must not fail here.
sed 's/^  1-2-an-active-story: in-progress$/  1-2-an-active-story: done/' \
  "$ACTIVE/$ARTIFACTS_REL/sprint-status.yaml" > "$ACTIVE/board.tmp" \
  && mv "$ACTIVE/board.tmp" "$ACTIVE/$ARTIFACTS_REL/sprint-status.yaml"
if check_repository "$ACTIVE"; then
  pass "in-progress spec is not held to the completed-spec invariant"
else
  fail "active spec was treated as a contradiction"
fi

echo ""
echo "=== Live repository ==="
if check_repository "$REPO_ROOT"; then
  pass "live repository board/spec statuses agree"
else
  fail "live repository has a real artifact-status contradiction (see STATUS CONTRADICTION lines above)"
fi

echo ""
if [[ "$FAIL" -eq 0 ]]; then
  echo "All $PASS artifact-status assertions passed."
  exit 0
fi
echo "$FAIL of $((PASS + FAIL)) artifact-status assertions failed." >&2
exit 1
